import { useState, useEffect, Suspense, useRef, useMemo } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { Points, PointMaterial, Preload } from '@react-three/drei'
import * as random from 'maath/random/dist/maath-random.esm'

// Helper to sanitize arrays generated by maath to guarantee no NaNs
const sanitizeArray = (arr) => {
  for (let i = 0; i < arr.length; i++) {
    if (isNaN(arr[i])) arr[i] = 0;
  }
  return arr;
};

// Subtle Star Layer for Upper Sections (Hero, About, Experience, Tech, Works, Certificates)
const SubtleStars = (props) => {
  const ref = useRef();
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);
    const handler = (e) => setPrefersReducedMotion(e.matches);
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, []);

  // Sparse ~500 particles for clean, calm cosmos
  const sphere = useMemo(() => {
    const raw = random.inSphere(new Float32Array(1500), { radius: 1.2 });
    return sanitizeArray(raw);
  }, []);

  useFrame((state, delta) => {
    if (prefersReducedMotion) return;
    if (ref.current) {
      ref.current.rotation.x -= delta / 35;
      ref.current.rotation.y -= delta / 45;
    }
  });

  return (
    <group rotation={[0, 0, Math.PI / 4]}>
      <Points ref={ref} positions={sphere} stride={3} frustumCulled {...props}>
        <PointMaterial
          transparent
          color="#38bdf8"
          size={0.0014}
          opacity={0.65}
          depthWrite={false}
          sizeAttenuation={true}
        />
      </Points>
    </group>
  );
};

// Rich Deep-Space Multi-Color Star Field for Contact & Footer
const DeepSpaceStars = (props) => {
  const refCyan = useRef();
  const refBlue = useRef();
  const refPink = useRef();
  const refPurple = useRef();
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);
    const handler = (e) => setPrefersReducedMotion(e.matches);
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, []);

  // Four distinct color spheres for dense deep space in Cyan, Blue, Pink, Purple
  const sphereCyan = useMemo(() => sanitizeArray(random.inSphere(new Float32Array(3000), { radius: 1.2 })), []);
  const sphereBlue = useMemo(() => sanitizeArray(random.inSphere(new Float32Array(2700), { radius: 1.15 })), []);
  const spherePink = useMemo(() => sanitizeArray(random.inSphere(new Float32Array(2100), { radius: 1.1 })), []);
  const spherePurple = useMemo(() => sanitizeArray(random.inSphere(new Float32Array(2100), { radius: 1.25 })), []);

  useFrame((state, delta) => {
    if (prefersReducedMotion) return;
    if (refCyan.current) {
      refCyan.current.rotation.x -= delta / 20;
      refCyan.current.rotation.y -= delta / 28;
    }
    if (refBlue.current) {
      refBlue.current.rotation.x += delta / 26;
      refBlue.current.rotation.y += delta / 34;
    }
    if (refPink.current) {
      refPink.current.rotation.x -= delta / 24;
      refPink.current.rotation.y += delta / 32;
    }
    if (refPurple.current) {
      refPurple.current.rotation.x += delta / 22;
      refPurple.current.rotation.y += delta / 30;
    }
  });

  return (
    <>
      {/* 1. Cyan Layer */}
      <group rotation={[0, 0, Math.PI / 4]}>
        <Points ref={refCyan} positions={sphereCyan} stride={3} frustumCulled {...props}>
          <PointMaterial
            transparent
            color="#22d3ee"
            size={0.0022}
            opacity={0.85}
            depthWrite={false}
            sizeAttenuation={true}
          />
        </Points>
      </group>

      {/* 2. Blue Layer */}
      <group rotation={[0, 0, -Math.PI / 6]}>
        <Points ref={refBlue} positions={sphereBlue} stride={3} frustumCulled {...props}>
          <PointMaterial
            transparent
            color="#38bdf8"
            size={0.0020}
            opacity={0.80}
            depthWrite={false}
            sizeAttenuation={true}
          />
        </Points>
      </group>

      {/* 3. Pink Layer */}
      <group rotation={[Math.PI / 6, 0, Math.PI / 3]}>
        <Points ref={refPink} positions={spherePink} stride={3} frustumCulled {...props}>
          <PointMaterial
            transparent
            color="#f43f85"
            size={0.0024}
            opacity={0.75}
            depthWrite={false}
            sizeAttenuation={true}
          />
        </Points>
      </group>

      {/* 4. Purple Layer */}
      <group rotation={[-Math.PI / 4, 0, -Math.PI / 4]}>
        <Points ref={refPurple} positions={spherePurple} stride={3} frustumCulled {...props}>
          <PointMaterial
            transparent
            color="#a855f7"
            size={0.0025}
            opacity={0.80}
            depthWrite={false}
            sizeAttenuation={true}
          />
        </Points>
      </group>
    </>
  );
};

const StarsCanvas = ({ density = 'subtle', fixed = true }) => {
  return (
    <div
      className={`w-full ${fixed ? 'h-full fixed' : 'h-full absolute'} inset-0 z-0 pointer-events-none overflow-hidden`}
      style={{ pointerEvents: 'none' }}
    >
      <Canvas
        camera={{ position: [0, 0, 1] }}
        gl={{
          alpha: true,
          powerPreference: 'low-power',
          antialias: false,
        }}
        dpr={[1, 1.5]}
        style={{ background: 'transparent' }}
        onCreated={({ gl }) => {
          gl.domElement.addEventListener('webglcontextlost', (e) => {
            e.preventDefault();
          });
        }}
      >
        <Suspense fallback={null}>
          {density === 'deep-space' ? <DeepSpaceStars /> : <SubtleStars />}
        </Suspense>
        <Preload all />
      </Canvas>
    </div>
  );
};

export default StarsCanvas;
